#requires -Version 5.1
[CmdletBinding()]param([ValidateRange(30,300)][int]$FreshSeconds=120)
$ErrorActionPreference='Stop';$repository=(Resolve-Path(Join-Path $PSScriptRoot '..')).Path;$now=[DateTimeOffset]::UtcNow
$rows=@();foreach($market in 'ES','NQ'){$manifest=Get-Content -LiteralPath(Join-Path $repository "data\ninjatrader_closed_bars\$market\manifest.json")-Raw|ConvertFrom-Json;$bridge=Get-Content -LiteralPath(Join-Path 'C:\Users\fjone\OneDrive\Documents\HermesBarBridge' $(if($market-eq'ES'){'MES.bar.json'}else{'MNQ.bar.json'}))-Raw|ConvertFrom-Json;$close=[DateTimeOffset]$bridge.close_time_utc;$age=($now-$close).TotalSeconds;$expectedArchive=$close.UtcDateTime.ToString('yyyy-MM-dd')+'.jsonl';if($manifest.market-ne$market-or$manifest.state-ne'RECORDING'-or$manifest.trading_authority-ne$false-or$manifest.archive_file-ne$expectedArchive-or[int]$manifest.scheduled_non_trading_minute_count-lt 0-or[int]$manifest.unresolved_gap_count-lt 0-or$age-gt$FreshSeconds){throw "$market post-maintenance evidence rejected."};$rows+=[ordered]@{market=$market;latest_close_utc=$bridge.close_time_utc;age_seconds=[math]::Round($age,1);scheduled_non_trading_minute_count=[int]$manifest.scheduled_non_trading_minute_count;unresolved_open_session_minute_count=[int]$manifest.unresolved_gap_count}}
$launchers=@(Get-CimInstance Win32_Process|Where-Object{$_.Name-eq'python.exe'-and$_.CommandLine-match '\.venv\\Scripts\\python.exe.*execution.ninjatrader_closed_bar_recorder_v1'});$task=Get-ScheduledTask -TaskName 'NinjaTrader MES-NQ Closed Bar Recorder' -TaskPath '\' -ErrorAction Stop;if($launchers.Count-ne 1-or[string]$task.State-ne'Running'){throw 'Recorder process isolation rejected.'}
$document=[ordered]@{schema_version='ninjatrader-post-maintenance-gate-v1';state='PASSED_WITH_QUARANTINED_OPEN_GAPS';observed_at=$now.ToString('o');markets=$rows;recorder_launcher_count=1;task_state='Running';current_day_canonical_eligible=$false;independent_recovery_replay_available=(Test-Path -LiteralPath(Join-Path $repository 'outputs\ninjatrader_gap_recovery\canonical-replay.json'));paper_execution_permitted=$false;trading_authority=$false};$target=Join-Path $repository 'outputs\operational_health\ninjatrader-post-maintenance-gate.json';$tmp="$target.$([guid]::NewGuid().ToString('N')).tmp";$document|ConvertTo-Json -Depth 5 -Compress|Set-Content -LiteralPath $tmp -Encoding UTF8;Move-Item -LiteralPath $tmp -Destination $target -Force;$document|ConvertTo-Json -Depth 5 -Compress
